// Commune : « NOM|département » ; nom en majuscules sans accents, comme DELTA
const norm = s => s.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase()
for (const c of communes) {
  const [nom, dep] = c.split('|')
  const rows = []
  const where = encodeURIComponent(`libelle_commune like "${norm(nom)}%"${dep ? ` and departement="${dep}"` : ''}`)
  for (let offset = 0; offset < 3000; offset += 100) {
    const r = await get(`${API}/${id}/records?where=${where}&limit=100&offset=${offset}`)
    if (!r.json) { out.erreurs = [...(out.erreurs ?? []), `${c} : ${r.status} ${r.text}`]; break }
    const res = r.json.results ?? []
    rows.push(...res.filter(x => Number(String(x.date_effet).slice(0, 4)) >= 2026))
    if (res.length < 100) break
  }
  out.communes[c] = rows
}
